"""Original Moonbite Votive Drummer action guides and immutable H3 recipes."""
import json,sys
import produce as p
UID='unit_mireclaw_moonbite_votive_drummers'
SELECTED=sys.argv[1:] if __name__=='__main__' else []
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original MOONBITE VOTIVE DRUMMER from the supplied painting, facing SCREEN RIGHT. One young human with the same original youthful unbearded face and long brown hair, a small branch/antler hair crest, dark green reed and leather clothes, wrapped leather shins and boots, and original amber lantern ornaments. Exactly TWO arms and TWO legs. Anatomical RIGHT arm is the near arm, visible on SCREEN LEFT at rest: that right hand continuously grips ONE short wooden mallet with a golden crescent-shaped head and green moss tassel. Anatomical LEFT arm is the far arm, visible on SCREEN RIGHT at rest: that left forearm and hand carry ONE small round woven wooden buckler with its dark central boss. Preserve its original attachment while allowing the original left-palm articulation above it. A SEPARATE round crescent-marked drum is strapped at the front of the waist; it is never the held buckler. Preserve all three original pieces of equipment and their grips, face, clothes, anatomical proportions and painted fantasy-game surface. ')
PLATE=(' Locked orthographic studio camera. Entire backdrop remains flat magenta RGB255,0,255, no scenery, floor, cast shadow, text, edits, cuts, zoom or camera movement. Fixed boot support plane y576 and unchanged anatomical scale; keep crest, crescent mallet, shield, waist drum, tassels and boots inside generous canvas margins. Preserve the existing amber ornaments without inventing flashes, stars, rings, particles, beams or extra weapons. ')

def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8
 return f

def recipe(clip,indices,guides,last,action,seed):
 if SELECTED and clip not in SELECTED:return
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True)
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=[reference(i) for i in indices],guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 if (out/'sampling_submission.json').exists() or (out/'submission.json').exists():
  assert json.loads((out/'config.json').read_bytes())==c,'Submitted recipe is immutable; use a new take'
  for guide in json.loads((out/'reference.json').read_bytes())['guides']:assert p.sha(out/guide['input_file'])==guide['input_sha256']
  print('Preserved submitted',clip,flush=True);return
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)

if __name__=='__main__':
 recipe('move',[16,2,3,4,11],[[26,1],[46,3],[70,2],[90,4]],0,'One full reciprocal WALK IN PLACE cycle. Near RIGHT boot extends forward and plants while far LEFT boot trails, near knee loads, then far boot passes and extends forward while the near boot trails. Finish in the exact original ready stance. Do not hop on one leg, slide, change body size or translate across the canvas. Mallet stays in the RIGHT hand and buckler stays on the LEFT arm; waist drum follows the pelvis naturally, never becoming a third held object. ',2026109031)
 recipe('attack',[16,5,6],[[32,1],[58,2]],0,'One short physical melee crescent-MALLET strike. Bend knees, lift the equipped RIGHT mallet forearm into the original windup, then drive that SAME gripped short mallet forward SCREEN RIGHT once with a clear contact; withdraw and recover. The LEFT-arm buckler stays carried in front of the far shoulder, and the separate waist drum stays strapped. This is a direct close-range mallet blow, not a drum beat or palm shove. No impact symbols or detached crescent projectile. ',2026109032)
 recipe('hit',[16,8],[[44,1]],0,'One clear impact recoil away from SCREEN RIGHT: torso leans backward, both knees flex and boots brace; RIGHT hand retains the crescent mallet, LEFT arm retains the buckler, strapped drum moves only with the torso. Recover once to the exact ready pose. No collapse, spinning, swapping hands, equipment loss or repeated impacts. ',2026109033)
 recipe('defend',[16,7],[[58,1]],1,'One continuous defensive brace. Bend both knees, lower the hips and bring the original LEFT-arm buckler up toward the face and chest; keep RIGHT mallet gripped low at the near side, protecting the separate waist drum. End held in the supplied crouched guard, with the final second completely still. Do not return to idle, punch, add a second shield or change arm count. ',2026109034)
 recipe('cast',[16,9,19],[[42,1],[82,2]],0,'One deliberate physical support salute. Slowly raise the original RIGHT crescent mallet beside and above the right shoulder, bring the LEFT-arm buckler closer to the chest, gently bow the head and flex both knees, hold the raised mallet as a rally cue, then lower it and recover to ready. This quiet raised-mallet salute is NOT a drum strike, volley, spell or weapon throw. Keep the separate crescent waist drum strapped and mallet in its original RIGHT-hand grip and buckler on its original LEFT arm. ',2026109035)
 recipe('ranged',[16,9,10],[[28,1],[48,2],[64,1],[82,2]],0,'One physical two-beat DRUM VOLLEY cue. The equipped RIGHT hand raises its original short crescent-headed mallet, lowers that same gripped mallet onto the separate strapped waist drum for the first beat, lifts it again, then strikes that same waist drum for one stronger second beat before recovering to the exact ready pose. The LEFT arm continues carrying its separate small buckler. Contact is on the waist drum, not on the buckler. Do not toss the mallet, strike an invisible target, change either disk into another object or add a bow. Runtime owns distant projectile flight; show only original held and strapped equipment, no dart, projectile, rings, flashes or magical beam. ',2026109036)
 recipe('death',[16,12,13,14,15],[[32,1],[66,2],[94,3]],4,'One continuous grounded collapse. Both knees buckle; lower the gripped RIGHT mallet toward the ground, kneel, tip onto the hip and forearm, then lay the torso and both folded legs fully down. The LEFT arm lowers its original buckler beside the body, and the separate crescent drum remains attached at the waist. Keep the mallet, buckler, two arms, two legs, hair crest, drum and costume intact. End in the supplied grounded corpse; final second still. No cuts, scale shrinking, upright floating equipment, resurrection, smoke or disintegration. ',2026109037)
 if not (p.SOURCE_DIR/'delivery.json').exists():
  p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','hit','defend','cast','ranged','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='All original24 packed poses and curated identity personally inspected. Existing idle16-23 has visible mallet/left-palm articulation, intact waist drum and buckler, stable boots and coherent return; preserve its exact eight original poses and240ms battle/map timing. Seven deficient actions await complete original/matte/native/reflected/actual action/map review.')))
 if not (p.SOURCE_DIR/'runtime_registration.json').exists():
  p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,canvas=[960,640],ground_anchor=[480,576],ready_guide=reference(16),reason='Original ready/action anatomical scales retained and divided by fixed extraction scale; one anatomical foot support plane, no frame normalization or stabilization.'))
